import"./chunk-7CGTOI24.js";var a={slug:"godzilla-minus-zero-o-que-saber",title:"Godzilla Minus Zero est\xE1 nos cinemas. Vale ver Minus One antes?",dek:"Takashi Yamazaki volta ao monstro depois do Oscar de efeitos visuais. Explicamos a liga\xE7\xE3o entre os dois filmes e o que j\xE1 d\xE1 para saber da continua\xE7\xE3o.",section:"filmes",kind:"noticia",tags:["Godzilla","Jap\xE3o","Estreias"],date:"2026-11-04",hero:{ref:"movie:1381071",pick:0,alt:"Godzilla em cena de Godzilla Minus Zero"},body:[{p:"*Godzilla Minus Zero* estreia nos cinemas brasileiros nesta quinta-feira (5). O filme da Toho \xE9 a continua\xE7\xE3o direta de *Godzilla Minus One*, de 2023, e traz de volta o diretor e roteirista Takashi Yamazaki e boa parte do elenco."},{ficha:"movie:1381071"},{h2:"O peso de Minus One"},{p:"*Minus One* foi um fen\xF4meno. Ambientado no Jap\xE3o logo ap\xF3s a Segunda Guerra, o filme usava o monstro para falar de culpa, trauma e reconstru\xE7\xE3o, e ganhou o Oscar de melhores efeitos visuais em mar\xE7o de 2024. Foi o primeiro filme da franquia a levar uma estatueta."},{p:"O feito chamou aten\xE7\xE3o tamb\xE9m pelo tamanho da equipe: cerca de 35 artistas do est\xFAdio Shirogumi, com o pr\xF3prio Yamazaki como supervisor de efeitos."},{ficha:"movie:940721"},{h2:"O que se sabe da continua\xE7\xE3o"},{p:"Segundo a sinopse oficial, a hist\xF3ria come\xE7a dois anos depois do ataque do primeiro filme. O Jap\xE3o ainda luta para se recuperar quando uma nova amea\xE7a surge e esmaga a esperan\xE7a que o pa\xEDs tinha acabado de reconstruir."},{p:"Ryunosuke Kamiki volta como Koichi Shikishima e Minami Hamabe como Noriko. Um detalhe curioso dos cr\xE9ditos: no primeiro filme ela aparece como Noriko Oishi, e agora como Noriko Shikishima. Yuki Yamada tamb\xE9m retorna como Shiro Mizushima."},{img:"movie:1381071",pick:2,caption:"Minus Zero tem 135 minutos e classifica\xE7\xE3o de 16 anos. Imagem de divulga\xE7\xE3o."},{h2:"Precisa ver Minus One antes?"},{p:"Recomendamos que sim. A for\xE7a de *Minus One* est\xE1 no arco de Shikishima, e a continua\xE7\xE3o parte exatamente desse ponto. Sem o primeiro filme, voc\xEA vai entender os sustos, mas perder o peso emocional."},{quote:"O Godzilla de Yamazaki assusta porque representa algo que o Jap\xE3o do p\xF3s-guerra conhecia bem: a sensa\xE7\xE3o de que tudo pode ser perdido de novo."},{box:"A reda\xE7\xE3o ainda n\xE3o assistiu a Godzilla Minus Zero. A opini\xE3o sobre Minus One \xE9 da reda\xE7\xE3o; as informa\xE7\xF5es do novo filme v\xEAm da Toho e do TMDB.",title:"Transpar\xEAncia"}]};var o={source:"TMDB + IGDB",updatedAt:"2026-11-10",calendar:[],games:{},movies:{940721:{id:940721,title:"Godzilla Minus One",original:"\u30B4\u30B8\u30E9-1.0",overview:"Em um Jap\xE3o social e economicamente devastado ap\xF3s o t\xE9rmino da Segunda Guerra Mundial, a situa\xE7\xE3o chega a um n\xEDvel ainda mais cr\xEDtico quando uma gigantesca e misteriosa criatura surge do mar para assolar o pa\xEDs.",poster:"/9XSOyim1pivuSHQqlrDj5gj2J5w.jpg",backdrops:["/oHBhHoNe59VH6bUMazDtJmWOFSS.jpg","/vlmiJOeDMbiyaJCAjFPtlkDcOEv.jpg","/bWIIWhnaoWx3FTVXv6GkYDv3djL.jpg","/fY3lD0jM5AoHJMunjGWqJ0hRteI.jpg","/pu6twJJq87vzYvtu0OftcN0AkNU.jpg"],runtime:125,genres:["Fic\xE7\xE3o cient\xEDfica","Terror","A\xE7\xE3o"],cert:"12",release:"2023-12-14",world:"2023-11-03",directors:["Takashi Yamazaki"],writers:["Takashi Yamazaki"],cast:[{name:"Ryunosuke Kamiki",role:"Koichi Shikishima"},{name:"Minami Hamabe",role:"Noriko Oishi"},{name:"Yuki Yamada",role:"Shiro Mizushima"},{name:"Munetaka Aoki",role:"Sosaku Tachibana"},{name:"Hidetaka Yoshioka",role:"Kenji Noda"},{name:"Sakura Ando",role:"Sumiko Ota"}],studios:["TOHO","TOHO Studios"],country:"JP"},1381071:{id:1381071,title:"Godzilla Minus Zero",original:"\u30B4\u30B8\u30E9-0.0",overview:"A guerra reduziu o Jap\xE3o a zero, e o Godzilla mergulhou-o no negativo. Passaram-se dois anos desde ent\xE3o, e o pa\xEDs tem enfrentado lutas agonizantes para alcan\xE7ar a recupera\xE7\xE3o e, finalmente, voltar \xE0 vida normal. No momento em que a humanidade conseguiu se agarrar a uma paz conquistada com dificuldade, surge uma nova amea\xE7a, esmagando a esperan\xE7a num instante.",poster:"/ebVZ8n64rtHsSItTei4EgTKzPVu.jpg",backdrops:["/oqrYIDH4tvfEzPe1yqT4jzmAWHQ.jpg","/drSQQgzsgXt9NIO9I2n6Bp4lBci.jpg","/rV6aarXKIRU5Nk5RfJdbrOLw05a.jpg","/oiL12oK3fiWCV6lA8zslI3H6zRK.jpg","/7QRn1bNoETZcCgdvtJpBCz67Rtv.jpg"],runtime:135,genres:["Fic\xE7\xE3o cient\xEDfica","Terror","A\xE7\xE3o"],cert:"16",release:"2026-11-05",world:"2026-11-03",directors:["Takashi Yamazaki"],writers:["Takashi Yamazaki"],cast:[{name:"Ryunosuke Kamiki",role:"Koichi Shikishima"},{name:"Minami Hamabe",role:"Noriko Shikishima"},{name:"Yuki Yamada",role:"Shiro Mizushima"},{name:"Kuranosuke Sasaki",role:"Seiji Akitsu"},{name:"Kunimura Jun",role:"Dr. Ogata"},{name:"Miou Tanaka",role:"Captain Tatsuo Hotta"}],studios:["TOHO","Robot Communications"],country:"JP"}},tv:{}};export{o as media,a as post};
